  "name": "Caesar cipher with shift 1",
  "idea": "Shift each letter by 1",
  "encrypt_rules": "shift_by_n(x, 1) = (x + 1) % 26",
  "decrypt_rules": "shift_by_n(x, 1) = (x - 1) % 26",
